def total_with_shipping(cart, shipping_fee, summary=None):
    s = 0.0
    for item in (cart or []):
        p = item.get('price', 0)
        if p is None:
            p = 0
        q = item.get('quantity', 1)
        if q is None:
            q = 1
        s += p * q
    total = s + shipping_fee
    return total
